API Request (Beta).code:
// Make a raw, authenticated request to the Stripe API.
// Paths are relative to https://api.stripe.com/v1. Bodies must be form-encoded.
fn(async state => {
  const { baseUrl = 'https://api.stripe.com', apiVersion = 'v1', apiKey } = state.configuration;

  const response = await util.request('GET', `${baseUrl}/${apiVersion}/refunds`, {
    headers: { Authorization: `Bearer ${apiKey}` },
    query: { limit: 10 },
    parseAs: 'json',
  });

  return { ...state, data: response.body };
});

Find Account Balance.code:
// Retrieve the current balance for the Stripe account.
// get() always appends '/{id}' to the path, and Stripe rejects GET /v1/balance/,
// so this calls the balance endpoint directly with util.request.
fn(async state => {
  const { baseUrl = 'https://api.stripe.com', apiVersion = 'v1', apiKey } = state.configuration;

  const response = await util.request('GET', `${baseUrl}/${apiVersion}/balance`, {
    headers: { Authorization: `Bearer ${apiKey}` },
    parseAs: 'json',
  });

  return { ...state, data: response.body };
});

